#[summary("task implementations")]
mod tasks {
    #[effects(pure)]
    #[uses(is_clamp, ordered)]
    fn clamp(x: i64, lo: i64, hi: i64) -> (r: i64)
        requires ordered(lo, hi),
        ensures is_clamp(x, lo, hi, r),
    {
        if x < lo {
            lo
        } else if x > hi {
            hi
        } else {
            x
        }
    }

    spec fn is_clamp(x: i64, lo: i64, hi: i64, r: i64) -> bool {
        x < lo && r == lo || x > hi && r == hi || lo <= x && x <= hi && r == x
    }

    spec fn ordered(lo: i64, hi: i64) -> bool {
        lo <= hi
    }
}

#[summary("midpoint: floor of the exact mean of two i64")]
mod tasks {
    #[effects(pure)]
    #[uses(is_floor_half)]
    fn floor_half(x: i64) -> (r: i64)
        ensures is_floor_half(x, r),
    {
        let q: i64 = x / 2;
        if x < 0 && x % 2 != 0 {
            q - 1
        } else {
            q
        }
    }

    spec fn is_floor_half(x: i64, r: i64) -> bool {
        2 * r <= x && x < 2 * r + 2
    }

    spec fn is_floor_mean(a: i64, b: i64, r: i64) -> bool {
        2 * r <= a + b && a + b < 2 * r + 2
    }

    #[effects(pure)]
    #[uses(is_floor_half, is_floor_mean)]
    fn midpoint(a: i64, b: i64) -> (r: i64)
        ensures is_floor_mean(a, b, r),
    {
        let ha: i64 = floor_half(a);
        let hb: i64 = floor_half(b);
        let s: i64 = ha + hb;
        if a % 2 != 0 && b % 2 != 0 {
            s + 1
        } else {
            s
        }
    }
}

#[summary("saturating sum of a slice")]
mod tasks {
    spec fn idx_ok(a: &[i64], i: usize) -> bool {
        i <= a.len()
    }

    spec fn is_sat_prefix(a: &[i64], n: usize, s: i64) -> bool {
        s == sat_prefix(a, n)
    }

    spec fn is_sat_sum(a: &[i64], r: i64) -> bool {
        r == sat_prefix(a, a.len())
    }

    spec fn sat_add(x: i64, y: i64) -> i64 {
        if y > 0 && x > 9223372036854775807 - y {
            9223372036854775807
        } else if y < 0 && x < -9223372036854775808 - y {
            -9223372036854775808
        } else {
            x + y
        }
    }

    spec fn sat_prefix(a: &[i64], n: usize) -> i64
        decreases n,
    {
        if n == 0 || n > a.len() {
            0
        } else {
            sat_add(sat_prefix(a, n - 1), a[n - 1])
        }
    }

    #[effects(pure)]
    #[uses(idx_ok, is_sat_prefix, is_sat_sum, sat_add, sat_prefix)]
    fn sat_sum(a: &[i64]) -> (r: i64)
        ensures is_sat_sum(a, r),
    {
        let mut s: i64 = 0;
        let mut i: usize = 0;
        while i < a.len()
            invariant idx_ok(a, i), is_sat_prefix(a, i, s),
            decreases a.len() - i,
        {
            let y: i64 = a[i];
            if y > 0 && s > 9223372036854775807 - y {
                s = 9223372036854775807;
            } else if y < 0 && s < -9223372036854775808 - y {
                s = -9223372036854775808;
            } else {
                s = s + y;
            }
            i = i + 1;
        }
        s
    }
}

#[summary("count elements in inclusive range")]
mod tasks {
    spec fn cnt(a: &[i64], lo: i64, hi: i64, n: usize) -> usize
        decreases n,
    {
        if n == 0 || n > a.len() {
            0
        } else {
            cnt(a, lo, hi, n - 1) + (if lo <= a[n - 1] && a[n - 1] <= hi { 1 } else { 0 })
        }
    }

    #[effects(pure)]
    #[uses(cnt, is_count, loop_inv)]
    fn count_in_range(a: &[i64], lo: i64, hi: i64) -> (r: usize)
        ensures is_count(a, lo, hi, r),
    {
        let mut i: usize = 0;
        let mut c: usize = 0;
        while i < a.len()
            invariant loop_inv(a, lo, hi, i, c),
            decreases a.len() - i,
        {
            if lo <= a[i] && a[i] <= hi {
                c = c + 1;
            }
            i = i + 1;
        }
        c
    }

    spec fn is_count(a: &[i64], lo: i64, hi: i64, r: usize) -> bool {
        r == cnt(a, lo, hi, a.len())
    }

    spec fn loop_inv(a: &[i64], lo: i64, hi: i64, i: usize, c: usize) -> bool {
        i <= a.len() && c <= i && c == cnt(a, lo, hi, i)
    }
}

#[summary("first index of the maximum element")]
mod tasks {
    #[effects(pure)]
    #[uses(first_max_upto, is_first_max, nonempty)]
    fn first_max_index(a: &[i64]) -> (r: usize)
        requires nonempty(a),
        ensures is_first_max(a, r),
    {
        let mut best: usize = 0;
        let mut i: usize = 1;
        while i < a.len()
            invariant first_max_upto(a, i, best),
            decreases a.len() - i,
        {
            if a[i] > a[best] {
                best = i;
            }
            i = i + 1;
        }
        best
    }

    spec fn first_max_upto(a: &[i64], n: usize, r: usize) -> bool {
        r < n && n <= a.len() && (forall|j: usize| j < n ==> #[trigger] a[j] <= a[r]) && (forall|k: usize| k < r ==> #[trigger] a[k] < a[r])
    }

    spec fn is_first_max(a: &[i64], r: usize) -> bool {
        r < a.len() && (forall|j: usize| j < a.len() ==> #[trigger] a[j] <= a[r]) && (forall|k: usize| k < r ==> #[trigger] a[k] < a[r])
    }

    spec fn nonempty(a: &[i64]) -> bool {
        a.len() > 0
    }
}

#[summary("last minimum index")]
mod tasks {
    spec fn inv(a: &[i64], m: usize, i: usize) -> bool {
        m < i && i <= a.len() && (forall|j: usize| j < i ==> a[m] <= #[trigger] a[j]) && (forall|k: usize| m < k && k < i ==> a[m] < #[trigger] a[k])
    }

    spec fn is_last_min(a: &[i64], r: usize) -> bool {
        r < a.len() && (forall|j: usize| j < a.len() ==> a[r] <= #[trigger] a[j]) && (forall|k: usize| r < k && k < a.len() ==> a[r] < #[trigger] a[k])
    }

    #[effects(pure)]
    #[uses(inv, is_last_min, nonempty)]
    fn last_min_index(a: &[i64]) -> (r: usize)
        requires nonempty(a),
        ensures is_last_min(a, r),
    {
        let mut m: usize = 0;
        let mut i: usize = 1;
        while i < a.len()
            invariant inv(a, m, i),
            decreases a.len() - i,
        {
            if a[i] <= a[m] {
                m = i;
            }
            i = i + 1;
        }
        m
    }

    spec fn nonempty(a: &[i64]) -> bool {
        a.len() > 0
    }
}

#[summary("strictly increasing check on i64 slices")]
mod tasks {
    spec fn loop_inv(a: &[i64], i: usize, ok: bool) -> bool {
        1 <= i && i <= a.len() && ok == prefix_inc(a, i)
    }

    spec fn prefix_inc(a: &[i64], k: usize) -> bool {
        forall|j: usize| j + 1 < k ==> #[trigger] a[j] < a[j + 1]
    }

    spec fn result_ok(a: &[i64], r: bool) -> bool {
        r == prefix_inc(a, a.len())
    }

    #[effects(pure)]
    #[uses(loop_inv, prefix_inc, result_ok)]
    fn strictly_increasing(a: &[i64]) -> (r: bool)
        ensures result_ok(a, r),
    {
        let n: usize = a.len();
        if n == 0 {
            true
        } else {
            let mut i: usize = 1;
            let mut ok: bool = true;
            while i < n
                invariant loop_inv(a, i, ok), n == a.len(),
                decreases n - i,
            {
                ok = ok && a[i - 1] < a[i];
                i = i + 1;
            }
            ok
        }
    }
}

#[summary("binary search lower_bound")]
mod tasks {
    spec fn above(a: &[i64], t: i64, hi: usize) -> bool {
        hi <= a.len() && (forall|k: usize| hi <= k && k < a.len() ==> #[trigger] a[k] >= t)
    }

    spec fn below(a: &[i64], t: i64, lo: usize) -> bool {
        lo <= a.len() && (forall|k: usize| k < lo ==> #[trigger] a[k] < t)
    }

    spec fn is_lower_bound(a: &[i64], t: i64, r: usize) -> bool {
        r <= a.len() && (forall|k: usize| k < r ==> #[trigger] a[k] < t) && (forall|m: usize| r <= m && m < a.len() ==> #[trigger] a[m] >= t)
    }

    #[effects(pure)]
    #[uses(above, below, is_lower_bound, sorted)]
    fn lower_bound(a: &[i64], t: i64) -> (r: usize)
        requires sorted(a),
        ensures is_lower_bound(a, t, r),
    {
        let mut lo: usize = 0;
        let mut hi: usize = a.len();
        while lo < hi
            invariant lo <= hi, below(a, t, lo), above(a, t, hi), sorted(a),
            decreases hi - lo,
        {
            let mid: usize = lo + (hi - lo) / 2;
            if a[mid] < t {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        lo
    }

    spec fn sorted(a: &[i64]) -> bool {
        forall|i: usize, j: usize| i <= j && j < a.len() ==> #[trigger] a[i] <= #[trigger] a[j]
    }
}

#[summary("floor division")]
mod tasks {
    #[effects(pure)]
    #[uses(domain, is_floor)]
    fn div_floor(a: i64, b: i64) -> (r: i64)
        requires domain(a, b),
        ensures is_floor(a, b, r),
    {
        let q: i64 = a / b;
        let rm: i64 = a % b;
        if rm != 0 && (rm < 0) != (b < 0) {
            q - 1
        } else {
            q
        }
    }

    spec fn domain(a: i64, b: i64) -> bool {
        b != 0 && !(a == -9223372036854775808 && b == -1)
    }

    spec fn is_floor(a: i64, b: i64, r: i64) -> bool {
        b > 0 && r * b <= a && a < r * b + b || b < 0 && r * b >= a && a > r * b + b
    }
}

#[summary("floor-division remainder")]
mod tasks {
    spec fn is_mod_floor(a: i64, b: i64, r: i64) -> bool {
        (b > 0 && 0 <= r && r < b || b < 0 && b < r && r <= 0) && (r == a % b || r == a % b + b || r == a % b - b)
    }

    #[effects(pure)]
    #[uses(is_mod_floor, nonzero)]
    fn mod_floor(a: i64, b: i64) -> (r: i64)
        requires nonzero(b),
        ensures is_mod_floor(a, b, r),
    {
        if b == -1 {
            0
        } else {
            let t: i64 = a % b;
            if t != 0 && (t < 0) != (b < 0) {
                t + b
            } else {
                t
            }
        }
    }

    spec fn nonzero(b: i64) -> bool {
        b != 0
    }
}

#[summary("maximum subarray sum (Kadane)")]
mod tasks {
    spec fn all_le(a: &[i64], k: usize, b: i64) -> bool {
        forall|i: usize, j: usize| i < j && j <= k ==> #[trigger] sum(a, i, j) <= b
    }

    spec fn ends_le(a: &[i64], k: usize, c: i64) -> bool {
        forall|i: usize| i < k ==> #[trigger] sum(a, i, k) <= c
    }

    spec fn in_dom(a: &[i64]) -> bool {
        a.len() >= 1 && a.len() <= 1000000 && (forall|i: usize| i < a.len() ==> -1000000000 <= #[trigger] a[i] && a[i] <= 1000000000)
    }

    spec fn is_max(a: &[i64], r: i64) -> bool {
        all_le(a, a.len(), r)
    }

    #[effects(pure)]
    #[uses(all_le, ends_le, in_dom, is_max, sum)]
    fn max_subarray(a: &[i64]) -> (r: i64)
        requires in_dom(a),
        ensures is_max(a, r),
    {
        let n: usize = a.len();
        let mut cur: i64 = a[0];
        let mut cs: usize = 0;
        let mut best: i64 = a[0];
        let mut bi: usize = 0;
        let mut bj: usize = 1;
        let mut k: usize = 1;
        while k < n
            invariant n == a.len(), in_dom(a), 1 <= k && k <= n, cs < k, bi < bj && bj <= k, -1000000000 <= cur && cur <= k * 1000000000, cur <= best && best <= k * 1000000000, cur == sum(a, cs, k), best == sum(a, bi, bj), ends_le(a, k, cur), all_le(a, k, best),
            decreases n - k,
        {
            let x: i64 = a[k];
            if cur + x >= x {
                cur = cur + x;
            } else {
                cur = x;
                cs = k;
            }
            k = k + 1;
            if cur > best {
                best = cur;
                bi = cs;
                bj = k;
            }
        }
        best
    }

    spec fn sum(a: &[i64], i: usize, j: usize) -> i64
        decreases j,
    {
        if j <= i || j > a.len() {
            0
        } else {
            sum(a, i, j - 1) + a[j - 1]
        }
    }
}

#[summary("second largest distinct value")]
mod tasks {
    spec fn is_max(a: &[i64], k: usize, m: i64) -> bool {
        k <= a.len() && (forall|i: usize| i < k ==> #[trigger] a[i] <= m) && (m == i64::MIN || !(forall|j: usize| j < k ==> #[trigger] a[j] != m))
    }

    spec fn is_second(a: &[i64], k: usize, m: i64, s: i64) -> bool {
        k <= a.len() && (forall|i: usize| i < k && #[trigger] a[i] < m ==> a[i] <= s) && (s == i64::MIN || s < m && !(forall|j: usize| j < k ==> #[trigger] a[j] != s))
    }

    #[effects(pure)]
    #[uses(is_max, is_second, second_max_of)]
    fn second_max(a: &[i64]) -> (r: i64)
        ensures second_max_of(a, r),
    {
        let mut m: i64 = i64::MIN;
        let mut s: i64 = i64::MIN;
        let mut k: usize = 0;
        while k < a.len()
            invariant is_max(a, k, m), is_second(a, k, m, s),
            decreases a.len() - k,
        {
            let x: i64 = a[k];
            if x > m {
                s = m;
                m = x;
            } else if x < m && x > s {
                s = x;
            }
            k = k + 1;
        }
        s
    }

    spec fn second_max_of(a: &[i64], r: i64) -> bool {
        (forall|i: usize, j: usize| i < a.len() && j < a.len() && #[trigger] a[i] > #[trigger] a[j] ==> a[j] <= r) && (r == i64::MIN || !(forall|p: usize| p < a.len() ==> #[trigger] a[p] != r) && !(forall|q: usize| q < a.len() ==> #[trigger] a[q] <= r))
    }
}

#[summary("array rotation tasks")]
mod tasks {
    spec fn range_ok(a: &[i64], lo: usize, hi: usize) -> bool {
        lo <= hi && hi <= a.len()
    }

    spec fn rev_inv(a: &[i64], o: &[i64], lo: usize, hi: usize, i: usize, j: usize) -> bool {
        a.len() == o.len() && lo <= i && i <= j && j <= hi && hi <= a.len() && i + j == lo + hi && (forall|x: usize| x < a.len() ==> #[trigger] a[x] == (if lo <= x && x < i || j <= x && x < hi { o[lo + hi - 1 - x] } else { o[x] }))
    }

    #[effects(pure)]
    #[uses(range_ok, rev_inv, reversed)]
    fn reverse_range(a: &mut [i64], lo: usize, hi: usize) -> ()
        requires range_ok(a, lo, hi),
        ensures reversed(a, old(a), lo, hi),
    {
        let mut i: usize = lo;
        let mut j: usize = hi;
        while j - i > 1
            invariant rev_inv(a, old(a), lo, hi, i, j),
            decreases j - i,
        {
            let t: i64 = a[i];
            a[i] = a[j - 1];
            a[j - 1] = t;
            i = i + 1;
            j = j - 1;
        }
    }

    spec fn reversed(a: &[i64], o: &[i64], lo: usize, hi: usize) -> bool {
        a.len() == o.len() && (forall|x: usize| x < a.len() ==> #[trigger] a[x] == (if lo <= x && x < hi { o[lo + hi - 1 - x] } else { o[x] }))
    }

    #[effects(pure)]
    #[uses(range_ok, reversed, rotated)]
    fn rotate_right(a: &mut [i64], k: usize) -> ()
        ensures rotated(a, old(a), k),
    {
        let n: usize = a.len();
        if n > 0 {
            let r: usize = k % n;
            reverse_range(a, 0, n);
            reverse_range(a, 0, r);
            reverse_range(a, r, n);
        }
    }

    spec fn rotated(a: &[i64], o: &[i64], k: usize) -> bool {
        a.len() == o.len() && (o.len() == 0 || (forall|x: usize| x < o.len() ==> (if x + k % o.len() < o.len() { a[x + k % o.len()] == #[trigger] o[x] } else { a[x + k % o.len() - o.len()] == o[x] })))
    }
}

#[summary("dedup of sorted slices")]
mod tasks {
    #[effects(pure)]
    #[uses(first_same, last_is, same_len, sorted, strict_prefix, tail_same, zero_range)]
    fn dedup_sorted(a: &mut [i64]) -> (r: usize)
        requires sorted(a),
        ensures same_len(a, old(a)), strict_prefix(a, r), zero_range(a, r, a.len()), first_same(old(a), a),
    {
        let n: usize = a.len();
        if n == 0 {
            0
        } else {
            let mut w: usize = 1;
            let mut i: usize = 1;
            while i < n
                invariant n == a.len(), sorted(old(a)), last_is(a, w, old(a), i), tail_same(a, old(a), i), strict_prefix(a, w), first_same(old(a), a),
                decreases n - i,
            {
                if a[i] != a[w - 1] {
                    a[w] = a[i];
                    w = w + 1;
                }
                i = i + 1;
            }
            let mut j: usize = w;
            while j < n
                invariant n == a.len(), w <= j, j <= n, strict_prefix(a, w), zero_range(a, w, j), same_len(a, old(a)), first_same(old(a), a),
                decreases n - j,
            {
                a[j] = 0;
                j = j + 1;
            }
            w
        }
    }

    spec fn first_same(a: &[i64], b: &[i64]) -> bool {
        a.len() == 0 || b.len() > 0 && a[0] == b[0]
    }

    spec fn last_is(a: &[i64], w: usize, b: &[i64], i: usize) -> bool {
        1 <= w && w <= i && i <= a.len() && i <= b.len() && a[w - 1] == b[i - 1]
    }

    spec fn same_len(a: &[i64], b: &[i64]) -> bool {
        a.len() == b.len()
    }

    spec fn sorted(a: &[i64]) -> bool {
        forall|k: usize| k + 1 < a.len() ==> #[trigger] a[k] <= a[k + 1]
    }

    spec fn strict_prefix(a: &[i64], r: usize) -> bool {
        r <= a.len() && (forall|k: usize| k + 1 < r ==> #[trigger] a[k] < a[k + 1])
    }

    spec fn tail_same(a: &[i64], b: &[i64], i: usize) -> bool {
        a.len() == b.len() && (forall|k: usize| i <= k && k < a.len() ==> #[trigger] a[k] == b[k])
    }

    spec fn zero_range(a: &[i64], lo: usize, hi: usize) -> bool {
        hi <= a.len() && (forall|k: usize| lo <= k && k < hi ==> #[trigger] a[k] == 0)
    }
}

#[summary("move zeros to the end of a slice, stable for non-zeros")]
mod tasks {
    spec fn below(o: &[i64], i: usize, w: usize) -> bool {
        forall|j: usize| j < i && #[trigger] o[j] != 0 ==> nz(o, j) < w
    }

    spec fn cnt(o: &[i64], i: usize, w: usize) -> bool {
        w == nz(o, i)
    }

    spec fn inv1(a: &[i64], n: usize, w: usize, i: usize) -> bool {
        w <= i && i <= n && a.len() == n
    }

    spec fn le(m: usize, w: usize) -> bool {
        m <= w
    }

    #[effects(pure)]
    #[uses(below, cnt, inv1, le, nz, placed, same_len, tail, zeros_between, zeros_from)]
    fn move_zeros(a: &mut [i64]) -> ()
        ensures same_len(a, old(a)), placed(a, old(a), a.len()), zeros_from(a, nz(old(a), a.len())),
    {
        let n: usize = a.len();
        let mut w: usize = 0;
        let mut i: usize = 0;
        while i < n
            invariant inv1(a, n, w, i), same_len(a, old(a)), cnt(old(a), i, w), below(old(a), i, w), placed(a, old(a), i), tail(a, old(a), i),
            decreases n - i,
        {
            let v: i64 = a[i];
            if v != 0 {
                a[w] = v;
                w = w + 1;
            }
            i = i + 1;
        }
        let m: usize = w;
        while w < n
            invariant inv1(a, n, w, n), same_len(a, old(a)), cnt(old(a), n, m), le(m, w), below(old(a), n, m), placed(a, old(a), n), zeros_between(a, m, w),
            decreases n - w,
        {
            a[w] = 0;
            w = w + 1;
        }
    }

    spec fn nz(a: &[i64], k: usize) -> usize
        decreases k,
    {
        if k == 0 {
            0
        } else {
            if a[k - 1] != 0 {
                nz(a, k - 1) + 1
            } else {
                nz(a, k - 1)
            }
        }
    }

    spec fn placed(a: &[i64], o: &[i64], i: usize) -> bool {
        forall|j: usize| j < i && #[trigger] o[j] != 0 ==> nz(o, j) < a.len() && a[nz(o, j)] == o[j]
    }

    spec fn same_len(a: &[i64], b: &[i64]) -> bool {
        a.len() == b.len()
    }

