#[summary("gcd of absolute values")]
mod tasks {
    #[effects(pure)]
    #[uses(in_domain, inv, is_gcd, sabs, sgcd)]
    fn gcd(a: i64, b: i64) -> (r: i64)
        requires in_domain(a, b),
        ensures is_gcd(a, b, r),
    {
        let mut x: i64 = if a < 0 {
            -a
        } else {
            a
        };
        let mut y: i64 = if b < 0 {
            -b
        } else {
            b
        };
        while y != 0
            invariant inv(a, b, x, y),
            decreases y,
        {
            let t: i64 = x % y;
            x = y;
            y = t;
        }
        x
    }

    spec fn in_domain(a: i64, b: i64) -> bool {
        a > i64::MIN && b > i64::MIN
    }

    spec fn inv(a: i64, b: i64, x: i64, y: i64) -> bool {
        x >= 0 && y >= 0 && sgcd(x, y) == sgcd(sabs(a), sabs(b))
    }

    spec fn is_gcd(a: i64, b: i64, r: i64) -> bool {
        r == sgcd(sabs(a), sabs(b))
    }

    spec fn sabs(x: i64) -> i64 {
        if x < 0 {
            -x
        } else {
            x
        }
    }

    spec fn sgcd(x: i64, y: i64) -> i64
        decreases y,
    {
        if y <= 0 || x < 0 {
            x
        } else {
            sgcd(y, x % y)
        }
    }
}

#[summary("integer square root")]
mod tasks {
    spec fn inv(n: i64, lo: i64, hi: i64) -> bool {
        0 <= lo && lo < hi && hi <= 3037000500 && lo * lo <= n && hi * hi > n
    }

    spec fn is_isqrt(n: i64, r: i64) -> bool {
        r >= 0 && r * r <= n && (r + 1) * (r + 1) > n
    }

    #[effects(pure)]
    #[uses(inv, is_isqrt, nonneg)]
    fn isqrt(n: i64) -> (r: i64)
        requires nonneg(n),
        ensures is_isqrt(n, r),
    {
        let mut lo: i64 = 0;
        let mut hi: i64 = 3037000500;
        while hi - lo > 1
            invariant inv(n, lo, hi),
            decreases hi - lo,
        {
            let mid: i64 = lo + (hi - lo) / 2;
            if mid <= n / mid {
                lo = mid;
            } else {
                hi = mid;
            }
        }
        lo
    }

    spec fn nonneg(n: i64) -> bool {
        n >= 0
    }
}

#[summary("range sum over half-open interval")]
mod tasks {
    spec fn domain(a: &[i64], i: usize, j: usize) -> bool {
        i <= j && j <= a.len() && a.len() <= 1000000 && (forall|k: usize| k < a.len() ==> -1000000000000 <= #[trigger] a[k] && a[k] <= 1000000000000)
    }

    spec fn inv(a: &[i64], i: usize, j: usize, k: usize, acc: i64) -> bool {
        i <= k && k <= j && acc == seg(a, i, k) && -((k - i) * 1000000000000) <= acc && acc <= (k - i) * 1000000000000
    }

    spec fn is_sum(a: &[i64], i: usize, j: usize, r: i64) -> bool {
        r == seg(a, i, j)
    }

    #[effects(pure)]
    #[uses(domain, inv, is_sum, seg)]
    fn range_sum(a: &[i64], i: usize, j: usize) -> (r: i64)
        requires domain(a, i, j),
        ensures is_sum(a, i, j, r),
    {
        let mut acc: i64 = 0;
        let mut k: usize = i;
        while k < j
            invariant domain(a, i, j), inv(a, i, j, k, acc),
            decreases j - k,
        {
            acc = acc + a[k];
            k = k + 1;
        }
        acc
    }

    spec fn seg(a: &[i64], i: usize, j: usize) -> i64
        decreases j,
    {
        if j <= i {
            0
        } else {
            seg(a, i, j - 1) + a[j - 1]
        }
    }
}

#[summary("majority element of a slice")]
mod tasks {
    spec fn count(a: &[i64], v: i64, n: usize) -> usize
        decreases n,
    {
        if n == 0 || n > a.len() {
            0
        } else {
            count(a, v, n - 1) + (if a[n - 1] == v { 1 } else { 0 })
        }
    }

    spec fn is_major(a: &[i64], v: i64) -> bool {
        count(a, v, a.len()) > a.len() / 2
    }

    #[effects(pure)]
    #[uses(count, is_major, ok)]
    fn majority(a: &[i64]) -> (r: i64)
        ensures ok(a, r),
    {
        let n: usize = a.len();
        let mut i: usize = 0;
        let mut res: i64 = i64::MIN;
        let mut found: bool = false;
        while i < n
            invariant i <= n, n == a.len(), found ==> is_major(a, res), !found ==> res == i64::MIN, !found ==> (forall|k: usize| k < i ==> !is_major(a, #[trigger] a[k])),
            decreases n - i,
        {
            let v: i64 = a[i];
            let mut c: usize = 0;
            let mut j: usize = 0;
            while j < n
                invariant j <= n, n == a.len(), i < n, v == a[i], c <= j, c == count(a, v, j),
                decreases n - j,
            {
                if a[j] == v {
                    c = c + 1;
                }
                j = j + 1;
            }
            if c > n / 2 {
                res = v;
                found = true;
                i = n;
            } else {
                i = i + 1;
            }
        }
        res
    }

    spec fn ok(a: &[i64], r: i64) -> bool {
        is_major(a, r) || r == i64::MIN && (forall|j: usize| j < a.len() ==> !is_major(a, #[trigger] a[j]))
    }
}

#[summary("longest run of consecutive equal elements")]
mod tasks {
    spec fn best(a: &[i64], n: usize) -> usize
        decreases n,
    {
        if n == 0 {
            0
        } else if best(a, n - 1) >= run_end(a, n - 1) {
            best(a, n - 1)
        } else {
            run_end(a, n - 1)
        }
    }

    spec fn inv(a: &[i64], i: usize, cur: usize, b: usize) -> bool {
        i <= a.len() && cur <= i && b == best(a, i) && (i == 0 || cur == run_end(a, i - 1))
    }

    spec fn is_longest(a: &[i64], r: usize) -> bool {
        r == best(a, a.len())
    }

    #[effects(pure)]
    #[uses(best, inv, is_longest, run_end)]
    fn longest_run(a: &[i64]) -> (r: usize)
        ensures is_longest(a, r),
    {
        let n: usize = a.len();
        let mut i: usize = 0;
        let mut cur: usize = 0;
        let mut b: usize = 0;
        while i < n
            invariant inv(a, i, cur, b),
            decreases n - i,
        {
            if i > 0 && a[i] == a[i - 1] {
                cur = cur + 1;
            } else {
                cur = 1;
            }
            if cur > b {
                b = cur;
            }
            i = i + 1;
        }
        b
    }

    spec fn run_end(a: &[i64], j: usize) -> usize
        decreases j,
    {
        if j == 0 {
            1
        } else if j >= a.len() {
            1
        } else if a[j] == a[j - 1] {
            run_end(a, j - 1) + 1
        } else {
            1
        }
    }
}

#[summary("merge of two sorted slices")]
mod tasks {
