    #[uses(idx_ok, len_ok, sorted, sorted_prefix, tail_le)]
    fn merge_sorted(a: &[i64], b: &[i64], out: &mut [i64]) -> ()
        requires sorted(a), sorted(b), len_ok(a, b, out),
        ensures sorted(out), len_ok(a, b, out),
    {
        let mut i: usize = 0;
        let mut j: usize = 0;
        let mut k: usize = 0;
        while k < out.len()
            invariant len_ok(a, b, out), idx_ok(a, b, i, j, k), sorted_prefix(out, k), tail_le(out, k, a, i), tail_le(out, k, b, j), sorted(a), sorted(b),
