#[summary("sorting tasks")]
mod tasks {
    spec fn inv1(a: &[i64], i: usize, j: usize) -> bool {
        j <= i && i < a.len() && (forall|k: usize, l: usize| k <= l && l <= i && k != j && l != j ==> #[trigger] a[k] <= #[trigger] a[l])
    }

