#[summary("modular exponentiation")]
mod tasks {
    spec fn dom(base: i64, exp: i64, m: i64) -> bool {
        base >= 0 && exp >= 0 && m >= 1 && m <= 3000000000
    }

    spec fn mm(a: i64, b: i64, m: i64) -> bool {
        0 <= a && a < m && 0 <= b && b < m && m >= 1 && m <= 3000000000
    }

    spec fn mr(r: i64, a: i64, b: i64, m: i64) -> bool {
        r == mulm(a, b, m) && 0 <= r && r < m
    }

    spec fn mulm(a: i64, b: i64, m: i64) -> i64 {
        a * b % m
    }

    #[effects(pure)]
    #[uses(mm, mr, mulm)]
    fn mulmod(a: i64, b: i64, m: i64) -> (r: i64)
        requires mm(a, b, m),
        ensures mr(r, a, b, m),
    {
        a * b % m
    }

    spec fn pm(b: i64, e: i64, m: i64) -> i64
        decreases e,
    {
        if e <= 0 {
            1 % m
        } else if e % 2 == 1 {
            mulm(mulm(pm(b, e / 2, m), pm(b, e / 2, m), m), b % m, m)
        } else {
            mulm(pm(b, e / 2, m), pm(b, e / 2, m), m)
        }
    }

    #[effects(pure)]
    #[uses(dom, mm, mr, pm, res)]
    fn pow_mod(base: i64, exp: i64, m: i64) -> (r: i64)
        requires dom(base, exp, m),
        ensures res(r, base, exp, m),
        decreases exp,
    {
        if exp == 0 {
            1 % m
        } else {
            let h: i64 = pow_mod(base, exp / 2, m);
            let h2: i64 = mulmod(h, h, m);
            if exp % 2 == 1 {
                let bm: i64 = base % m;
                mulmod(h2, bm, m)
            } else {
                h2
            }
        }
    }

    spec fn res(r: i64, base: i64, exp: i64, m: i64) -> bool {
        r == pm(base, exp, m) && 0 <= r && r < m
    }
}
